    end_time: Optional[datetime.datetime] = None
    started_at: Optional[datetime.datetime] = None

    def __post_init__(self):
        self.type = ClockType.TIMER
        if self.end_time is None and self.started_at is not None:
            self.end_time = self.started_at + datetime.timedelta(seconds=self.duration_seconds)

