            time.sleep(1)  # 每秒检查一次

    def start_monitoring(self) -> None:
        """开始监控事件"""
        if not self._running:
            self._running = True
            self._thread = threading.Thread(target=self._monitor_loop, daemon=True)
            self._thread.start()

    def stop_monitoring(self) -> None:
        """停止监控事件"""
        self._running = False
