                events_data = json.load(f)

            self.events.clear()
            for event_data in events_data:
                try:
                    event = ClockEvent.from_dict(event_data)
                    self.events[event.id] = event
                except Exception as e:
                    print(f"加载事件失败: {e}")
        except Exception as e:
            print(f"加载事件文件失败: {e}")

    def _check_events(self) -> None:
        """检查事件是否触发"""
        now = datetime.datetime.now()

        for event in self.get_active_events():
            if isinstance(event, Alarm) and event.is_time_to_ring():
                self._notify_callbacks(event)
                # 如果不是重复闹钟，触发后禁用
                if not event.repeat_days:
                    event.active = False
                    self.save_events()

            elif isinstance(event, Reminder) and event.is_time_to_remind():
                self._notify_callbacks(event)
                event.active = False
                self.save_events()

            elif isinstance(event, Timer) and event.is_finished():
                self._notify_callbacks(event)
                event.active = False
                self.save_events()

    def _monitor_loop(self) -> None:
        """监控循环"""
        while self._running:
            self._check_events()
            time.sleep(1)  # 每秒检查一次

    def start_monitoring(self) -> None:
        """开始监控事件"""
        if not self._running:
            self._running = True
            self._thread = threading.Thread(target=self._monitor_loop, daemon=True)
            self._thread.start()

    def stop_monitoring(self) -> None:
        """停止监控事件"""
        self._running = False
        if self._thread:
            self._thread.join(timeout=2)
            self._thread = None

