            '周末': [5, 6],  # 周六周日
            '周一': [0], '周二': [1], '周三': [2], '周四': [3], 
            '周五': [4], '周六': [5], '周日': [6]
        }

        for day_key, days in day_keywords.items():
            if day_key in message:
                repeat_days = days
                break

        # 创建闹钟
        alarm = self.clock_manager.create_alarm(name, time_str, repeat_days)

        # 生成响应
        response = f"✅ 已创建闹钟：{name}\n"
        response += f"   时间：{time_str}\n"
        if repeat_days:
            day_names = ['周一', '周二', '周三', '周四', '周五', '周六', '周日']
            repeat_text = '、'.join([day_names[i] for i in repeat_days])
            response += f"   重复：{repeat_text}\n"
        else:
            response += "   重复：仅一次\n"
        response += f"   ID：{alarm.id[:8]}"

        return response

    def _parse_reminder(self, message: str) -> str:
        """解析提醒设置"""
        # 提取时间
        time_patterns = [
            r'(\d{1,2}):(\d{2})',  # HH:MM
            r'(\d+)分钟后',  # X分钟后
            r'(\d+)小时后',  # X小时后
            r'今天(\d{1,2})点(\d{1,2})分',  # 今天X点Y分
            r'明天(\d{1,2})点(\d{1,2})分',  # 明天X点Y分
        ]

        trigger_time = None
        for pattern in time_patterns:
            match = re.search(pattern, message)
            if match:
                if pattern == r'(\d+)分钟后':
                    minutes = int(match.group(1))
                    trigger_time = datetime.datetime.now() + datetime.timedelta(minutes=minutes)
                elif pattern == r'(\d+)小时后':
                    hours = int(match.group(1))
                    trigger_time = datetime.datetime.now() + datetime.timedelta(hours=hours)
                elif '今天' in pattern:
                    hour, minute = map(int, match.groups())
                    today = datetime.datetime.now().date()
                    trigger_time = datetime.datetime.combine(today, datetime.time(hour, minute))
                elif '明天' in pattern:
                    hour, minute = map(int, match.groups())
                    tomorrow = datetime.datetime.now().date() + datetime.timedelta(days=1)
                    trigger_time = datetime.datetime.combine(tomorrow, datetime.time(hour, minute))
                else:
                    hour, minute = map(int, match.groups())
                    today = datetime.datetime.now().date()
                    trigger_time = datetime.datetime.combine(today, datetime.time(hour, minute))
                break

        if not trigger_time:
            return "请指定提醒时间，例如：'5分钟后提醒我吃药' 或 '设置今天14:30的会议提醒'"

        # 提取消息内容
        message_content = "提醒"
        content_match = re.search(r'提醒我(.+?)(?:$|，|。|！|!)', message)
        if content_match:
            message_content = content_match.group(1).strip()

        # 提取名称
        name_match = re.search(r'["\'](.+?)["\']', message)
        name = name_match.group(1) if name_match else "提醒"

        # 创建提醒
        reminder = self.clock_manager.create_reminder(name, message_content, trigger_time)

        # 生成响应
        response = f"✅ 已创建提醒：{name}\n"
        response += f"   内容：{message_content}\n"
        response += f"   时间：{trigger_time.strftime('%Y-%m-%d %H:%M')}\n"
        response += f"   ID：{reminder.id[:8]}"

        return response

    def _parse_timer(self, message: str, time_info: Tuple) -> str:
        """解析倒计时设置"""
        # 提取名称
        name_match = re.search(r'["\'](.+?)["\']', message)
        name = name_match.group(1) if name_match else "倒计时"

        # 解析时长
        duration_seconds = 0

        if '分钟' in message or '分' in message:
            minutes = int(time_info[0])
            duration_seconds = minutes * 60
        elif '小时' in message or '时' in message:
            hours = int(time_info[0])
            duration_seconds = hours * 3600
        elif '秒' in message:
            seconds = int(time_info[0])
            duration_seconds = seconds
        else:
            # 默认按分钟处理
            minutes = int(time_info[0])
            duration_seconds = minutes * 60

        # 创建倒计时
        timer = self.clock_manager.create_timer(name, duration_seconds)
        started_timer = self.clock_manager.start_timer(timer.id)

        if started_timer:
            # 生成响应
            end_time = started_timer.end_time.strftime('%H:%M:%S') if started_timer.end_time else "未知"
            response = f"✅ 已开始倒计时：{name}\n"
            response += f"   时长：{duration_seconds}秒 ({duration_seconds//60}分{duration_seconds%60}秒)\n"
            response += f"   结束时间：{end_time}\n"
            response += f"   ID：{timer.id[:8]}"
            return response
        else:
            return "❌ 无法开始倒计时"

    def _parse_delete(self, message: str) -> str:
        """解析删除命令"""
        # 提取ID或名称
        id_match = re.search(r'ID[:：]?\s*(\w+)', message)
        name_match = re.search(r'["\'](.+?)["\']', message)

        if id_match:
            event_id = id_match.group(1)
            # 查找完整ID
            for event in self.clock_manager.events.values():
                if event.id.startswith(event_id):
                    if self.clock_manager.delete_event(event.id):
                        return f"✅ 已删除事件：{event.name}"
                    else:
                        return "❌ 删除失败"
            return "❌ 未找到对应ID的事件"

        elif name_match:
            name = name_match.group(1)
            # 查找同名事件
            deleted = []
            for event in list(self.clock_manager.events.values()):
                if event.name == name:
                    if self.clock_manager.delete_event(event.id):
                        deleted.append(event.name)

            if deleted:
                return f"✅ 已删除 {len(deleted)} 个事件：{', '.join(deleted)}"
            else:
                return "❌ 未找到对应名称的事件"

        else:
            return "请指定要删除事件的ID或名称，例如：'删除ID:abc123' 或 '删除\"我的闹钟\"'"

    def _parse_toggle(self, message: str, enable: bool) -> str:
        """解析开关命令"""
        # 提取ID或名称
        id_match = re.search(r'ID[:：]?\s*(\w+)', message)
        name_match = re.search(r'["\'](.+?)["\']', message)

        action = "开启" if enable else "关闭"

        if id_match:
            event_id = id_match.group(1)
            # 查找完整ID
            for event in self.clock_manager.events.values():
                if event.id.startswith(event_id):
                    toggled = self.clock_manager.toggle_event(event.id)
                    if toggled:
                        status = "已激活" if toggled.active else "已禁用"
                        return f"✅ 已{action}事件：{toggled.name} ({status})"
                    else:
                        return "❌ 操作失败"
            return "❌ 未找到对应ID的事件"

        elif name_match:
            name = name_match.group(1)
            # 查找同名事件
            toggled_events = []
            for event in self.clock_manager.events.values():
                if event.name == name:
                    toggled = self.clock_manager.toggle_event(event.id)
                    if toggled:
                        status = "已激活" if toggled.active else "已禁用"
                        toggled_events.append(f"{toggled.name} ({status})")

            if toggled_events:
                return f"✅ 已{action} {len(toggled_events)} 个事件：\n" + "\n".join(toggled_events)
            else:
                return "❌ 未找到对应名称的事件"

        else:
            return f"请指定要{action}事件的ID或名称，例如：'{action}ID:abc123' 或 '{action}\"我的闹钟\"'"

    def _list_alarms(self) -> str:
        """列出所有闹钟"""
        alarms = self.clock_manager.get_events_by_type(ClockType.ALARM)

        if not alarms:
            return "📭 暂无闹钟"

        response = "⏰ 闹钟列表：\n"
        for i, alarm in enumerate(alarms, 1):
            status = "✅" if alarm.active else "❌"
            repeat_text = "每天" if alarm.repeat_days == list(range(7)) else \
                         "工作日" if alarm.repeat_days == [0, 1, 2, 3, 4] else \
                         "周末" if alarm.repeat_days == [5, 6] else \
                         "仅一次" if not alarm.repeat_days else "自定义"

            response += f"{i}. {status} {alarm.name} - {alarm.time.strftime('%H:%M')} ({repeat_text}) [ID:{alarm.id[:8]}]\n"

        return response.strip()

    def _list_reminders(self) -> str:
        """列出所有提醒"""
        reminders = self.clock_manager.get_events_by_type(ClockType.REMINDER)

        if not reminders:
            return "📭 暂无提醒"

        response = "📝 提醒列表：\n"
        for i, reminder in enumerate(reminders, 1):
            status = "✅" if reminder.active else "❌"
            time_str = reminder.trigger_time.strftime('%m-%d %H:%M')
            response += f"{i}. {status} {reminder.name} - {time_str}: {reminder.message} [ID:{reminder.id[:8]}]\n"

        return response.strip()

    def _list_timers(self) -> str:
        """列出所有倒计时"""
        timers = self.clock_manager.get_events_by_type(ClockType.TIMER)

        if not timers:
            return "📭 暂无倒计时"

        response = "⏱️ 倒计时列表：\n"
        for i, timer in enumerate(timers, 1):
            status = "✅" if timer.active else "❌"
            remaining = timer.get_remaining_time()
            if remaining:
                hours, remainder = divmod(remaining.seconds, 3600)
                minutes, seconds = divmod(remainder, 60)
                time_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
            else:
                time_str = "未开始"

            response += f"{i}. {status} {timer.name} - 剩余: {time_str} [ID:{timer.id[:8]}]\n"

        return response.strip()

    def _list_all(self) -> str:
        """列出所有事件"""
        alarms = self._list_alarms()
        reminders = self._list_reminders()
        timers = self._list_timers()

        response = "📋 所有事件：\n\n"
        response += alarms + "\n\n" if "暂无" not in alarms else ""
        response += reminders + "\n\n" if "暂无" not in reminders else ""
        response += timers if "暂无" not in timers else ""

        if response == "📋 所有事件：\n\n":
            return "📭 暂无任何事件"

        return response.strip()

